leeting","type":"word","part_of_speech":"adjective","meaning":"mưa tuyết","category":"Weather","status":"learning","ipa":"/ˈsliː.tɪŋ/","image_path":"default-vocabulary/weather/sleeting.jpg"},{"word":"lightning","type":"word","part_of_speech":"noun","meaning":"sét","category":"Weather","status":"learning","ipa":"/ˈlaɪt.nɪŋ/","image_path":"default-vocabulary/weather/lightning.jpg"},{"word":"partly cloudy","type":"word","part_of_speech":"adjective","meaning":"trời có mây rải rác","category":"Weather","status":"learning","ipa":"/ˈpɑːrt.li ˈklaʊ.di/","image_path":"default-vocabulary/weather/partly-cloudy.jpg"}]'::jsonb;
  v_item jsonb;
  v_word_id uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A user ID is required to seed default vocabulary packs.';
  END IF;

  FOR v_item IN
    SELECT value FROM pg_catalog.jsonb_array_elements(v_items) AS items(value)
  LOOP
    IF EXISTS (
      SELECT 1 FROM public.vocabulary_words AS words
      WHERE words.user_id = p_user_id
        AND pg_catalog.lower(words.word) = pg_catalog.lower(v_item->>'word')
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.vocabulary_words (user_id, word, meaning, category, status, type, ipa, image_path)
    VALUES (
      p_user_id, v_item->>'word', v_item->>'meaning', v_item->>'category',
      COALESCE(NULLIF(v_item->>'status', ''), 'learning'),
      COALESCE(NULLIF(v_item->>'type', ''), 'word'),
      NULLIF(v_item->>'ipa', ''), v_item->>'image_path'
    )
    RETURNING id INTO v_word_id;

    IF NULLIF(v_item->>'part_of_speech', '') IS NOT NULL THEN
      INSERT INTO public.vocabulary_meanings (vocabulary_word_id, part_of_speech, meaning)
      VALUES (v_word_id, v_item->>'part_of_speech', v_item->>'meaning');
    END IF;
  END LOOP;
END;
$$;

REVOKE ALL PRIVILEGES ON FUNCTION public.seed_remaining_default_vocabulary_packs_for_user(uuid) FROM PUBLIC, anon, authenticated;

-- Replace the legacy 90-word starter with the complete image-backed dataset for future signups.
CREATE OR REPLACE FUNCTION public.create_default_vocabulary_categories_for_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  INSERT INTO public.vocabulary_categories (user_id, name, color, is_default)
  VALUES
    (NEW.id, 'Uncategorized', 'blue', true),
    (NEW.id, 'Fruits', 'green', false),
    (NEW.id, 'Colors', 'violet', false),
    (NEW.id, 'Animals', 'orange', false),
    (NEW.id, 'Family', 'rose', false),
    (NEW.id, 'Body', 'blue', false),
    (NEW.id, 'Supplies', 'violet', false),
    (NEW.id, 'Time', 'orange', false),
    (NEW.id, 'Weather', 'blue', false),
    (NEW.id, 'Clothes', 'rose', false),
    (NEW.id, 'Numbers', 'green', false),
    (NEW.id, 'School', 'blue', false),
    (NEW.id, 'House', 'orange', false),
    (NEW.id, 'Shapes', 'violet', false),
    (NEW.id, 'Food', 'green', false),
    (NEW.id, 'Jobs', 'blue', false),
    (NEW.id, 'Transport', 'orange', false),
    (NEW.id, 'Feelings', 'rose', false),
    (NEW.id, 'Actions', 'violet', false)
  ON CONFLICT DO NOTHING;

  PERFORM public.seed_default_vocabulary_pack_for_user(NEW.id);
  PERFORM public.seed_remaining_default_vocabulary_packs_for_user(NEW.id);
  RETURN NEW;
END;
$$;

-- Seed empty accounts and accounts already using shared starter images; leave fully custom accounts untouched.
DO $$
DECLARE
  v_user_id uuid;
BEGIN
  FOR v_user_id IN
    SELECT users.id
    FROM auth.users AS users
    WHERE NOT EXISTS (
      SELECT 1 FROM public.vocabulary_words AS words WHERE words.user_id = users.id
    )
    OR EXISTS (
      SELECT 1 FROM public.vocabulary_words AS words
      WHERE words.user_id = users.id
        AND words.image_path LIKE 'default-vocabulary/%'
    )
  LOOP
    INSERT INTO public.vocabulary_categories (user_id, name, color, is_default)
    VALUES
      (v_user_id, 'Uncategorized', 'blue', true),
      (v_user_id, 'Fruits', 'green', false),
      (v_user_id, 'Colors', 'violet', false),
      (v_user_id, 'Animals', 'orange', false),
      (v_user_id, 'Family', 'rose', false),
      (v_user_id, 'Body', 'blue', false),
      (v_user_id, 'Supplies', 'violet', false),
      (v_user_id, 'Time', 'orange', false),
      (v_user_id, 'Weather', 'blue', false),
      (v_user_id, 'Clothes', 'rose', false),
      (v_user_id, 'Numbers', 'green', false),
      (v_user_id, 'School', 'blue', false),
      (v_user_id, 'House', 'orange', false),
      (v_user_id, 'Shapes', 'violet', false),
      (v_user_id, 'Food', 'green', false),
      (v_user_id, 'Jobs', 'blue', false),
      (v_user_id, 'Transport', 'orange', false),
      (v_user_id, 'Feelings', 'rose', false),
      (v_user_id, 'Actions', 'violet', false)
    ON CONFLICT DO NOTHING;
    PERFORM public.seed_default_vocabulary_pack_for_user(v_user_id);
    PERFORM public.seed_remaining_default_vocabulary_packs_for_user(v_user_id);
  END LOOP;
END;
$$;

COMMIT;
